+    afterEach(() => jest.restoreAllMocks());
+
+    it.each([
+        ['Mac OS', 'Safari'],
+        ['iOS', 'Mobile Safari'],
+    ])('supports HEIC, HEIF and JXL on %s %s 17+', (os, name) => {
+        jest.spyOn(browser, 'getOS').mockReturnValue({ name: os, version: '17.0' });
