+        expect(isSupportedImage(SupportedMimeTypes.heif)).toBe(true);
+        expect(isSupportedImage(SupportedMimeTypes.heifs)).toBe(true);
+        expect(isSupportedImage(SupportedMimeTypes.jxl)).toBe(true);
+    });
+
+    it.each([
+        ['Mac OS', 'Safari', '16.6'],
+        ['iOS', 'Mobile Safari', '16.6'],
+        ['Windows', 'Safari', '17.0'],
+        ['Mac OS', 'Chrome', '17.0'],
+    ])('rejects modern images on %s %s %s', (os, name, version) => {
+        jest.spyOn(browser, 'getOS').mockReturnValue({ name: os, version: '' });
+        jest.spyOn(browser, 'getBrowser').mockReturnValue({ name, version, major: version.split('.')[0] });
+
